import{_ as t,a as e}from"./chunks/L0C_Memory_Structure_950.CNBZUcQv.js";import{_ as i,o as r,a as n,b as p}from"./app.Zc0CUjTy.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"L0C Buffer内存结构介绍","link":"/api/SIMD-API/c_api/cube_datamove/L0C_memory_structure_intro"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/L0C_memory_structure_intro.md","filePath":"api/SIMD-API/c_api/cube_datamove/L0C_memory_structure_intro.md","outlineHeaders":[{"level":2,"title":"C API寻址与同步","slug":"C-API寻址与同步","link":"#C-API寻址与同步"}],"lastUpdated":1789544578000}'),_={name:"api/SIMD-API/c_api/cube_datamove/L0C_memory_structure_intro.md"};function o(s,a,d,c,l,B){return r(),n("div",null,[...a[0]||(a[0]=[p(`<div><article class="markdown-body"><h1>L0C Buffer内存结构介绍</h1><p>为提升数据访问效率和吞吐量，L0C Buffer采用了等容量的内存模块（Bank）结构设计。内存空间被划分为多个Bank，并以Bank为单位进一步分组形成多个Bank Group（BG）；每个Bank Group包含若干Bank，每个Bank都是一个可独立操作的存储单元子模块。</p><div data-filter="A3,910b"><p>以如下产品型号为例：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><p>L0C Buffer的总容量为128K字节，由16个Bank组成。每个Bank的容量为8K字节，由128行组成，每行的宽度为64字节。这16个Bank被进一步组织为16个Bank Group。每个Bank Group包含1个Bank。</p><p>L0C Buffer的内存结构如下图1所示，L0C Buffer的地址编码格式及其bit位对应的含义说明如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>L0C_ADDR[16:0] = { BANK_DEPTH[6:0], BANK[3:0], BANK_WIDTH[5:0] }    // bit位顺序为从高位到低位，共17位
// BANK_DEPTH表示地址在Bank中的行数，占用7位bit位，取值范围为[0, 127]
// BANK表示地址所在Bank的编号，占用4位bit位，取值范围为[0, 15]
// BANK_WIDTH表示地址在Bank一行上的偏移量，占用6位bit位，取值范围为[0, 63]
</code></pre></div><p><strong>图1</strong> L0C Buffer内存结构图（<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><p><img src="`+t+`" alt></p></div><div data-filter="950"><p>以Ascend 950PR/Ascend 950DT为例，L0C Buffer总容量为256K字节，由16个Bank组成。每个Bank的容量为16K字节，由256行组成，每行的宽度为64字节。这16个Bank被进一步组织为16个Bank Group。每个 Bank Group包含1个Bank。</p><p>L0C Buffer的内存结构如下图2所示，L0C Buffer的地址编码格式及其bit位对应的含义说明如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>L0C_ADDR[17:0] = { BANK_DEPTH[7:0], BANK[3:0], BANK_WIDTH[5:0] }    // bit位顺序为从高位到低位，共18位
// BANK_DEPTH表示地址在Bank中的行数，占用8位bit位，取值范围为[0, 255]
// BANK表示地址所在Bank的编号，占用4位bit位，取值范围为[0, 15]
// BANK_WIDTH表示地址在Bank一行上的偏移量，占用6位bit位，取值范围为[0, 63]
</code></pre></div><p><strong>图2</strong> L0C Buffer内存结构图（<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><p><img src="`+e+'" alt></p></div><h2 id="C-API寻址与同步">C API寻址与同步<a class="header-anchor" href="#C-API寻址与同步">​</a></h2><p>L0C Buffer使用<code>__cc__ float*</code>或<code>__cc__ int32_t*</code>存放累加结果，一个16×16结果分形占1024B，地址需同时满足计算和搬出接口的对齐要求。搬出起始地址按64B对齐，<code>src_stride</code>按64B计数；不能把L0A Buffer/L0B Buffer的512B输入分形单位用作该步长单位。</p><p><a href="../cube_compute/mmad_compute_key_features/UnitFlag.html">UnitFlag</a>以512B块管理读写状态，一个完整的1024B结果分形涉及两个标志块。Bank结构、结果分形和UnitFlag块是不同概念。</p></article></div>',1)])])}const m=i(_,[["render",o]]);export{h as __pageData,m as default};
